(function(){const st=document.createElement('style');st.textContent=`
.ct{background:#fff;color:#1c1c1e;border-radius:14px;padding:28px 24px;font-family:Georgia,'Times New Roman',serif;font-size:.9rem;line-height:1.5;box-shadow:0 1px 3px rgba(0,0,0,.08)}
.ct h2{font-family:inherit;color:#1A2B5C;font-size:1.25rem;text-align:center;margin:6px 0 2px}.ct .sub{text-align:center;color:#555;font-size:.82rem}
.ct h3{background:#1A2B5C;color:#fff;font-size:.82rem;letter-spacing:.02em;padding:5px 10px;margin:18px 0 8px;font-family:inherit}
.ct h4{color:#1A2B5C;font-size:.9rem;margin:12px 0 4px;border-bottom:1px solid #D6E4F7;padding-bottom:2px;font-family:inherit}
.ct table{width:100%;border-collapse:collapse;margin:6px 0;font-size:.82rem}.ct td{border:1px solid #D0DCF0;padding:5px 8px;vertical-align:top}.ct td:first-child{background:#D6E4F7;color:#1A2B5C;font-weight:bold;width:38%}
.ct .box{border:1px solid #D0DCF0;background:#F4F8FD;padding:8px 10px;margin:8px 0;font-size:.84rem}.ct .warn{border-color:#A8392D;background:#FBF1EF}
.ct .ksig{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-top:10px}.ct .ksig>div{border:1px solid #D0DCF0;padding:10px;min-height:120px}.ct .ksig img{max-width:100%;height:70px;object-fit:contain;display:block}
.ct .head{text-align:center;color:#1A2B5C;font-weight:bold;letter-spacing:.06em}.ct .meta{text-align:center;font-size:.75rem;color:#666}
.ct .fill{color:#0B5D4B;font-weight:bold}.ct .empty{color:#A8392D}
.sigpad{border:2px dashed var(--line);border-radius:14px;background:#fff;touch-action:none;width:100%;height:180px;display:block}
.dz label.f{margin-top:0}.dz .fields{margin-bottom:6px}
@media print{body *{visibility:hidden!important}.ct,.ct *{visibility:visible!important}.ct{position:absolute;left:0;top:0;width:100%;box-shadow:none;padding:0}}
@media (max-width:600px){.ct{padding:18px 14px;font-size:.86rem}.ct .ksig{grid-template-columns:1fr}}`;document.head.appendChild(st)})();

S.dossiers={};S.contrats=[];
const _bootExtra16=bootExtra;
bootExtra=function(db){_bootExtra16(db);
  try{db.collection('dossiers').onSnapshot(q=>{S.dossiers={};q.docs.forEach(d=>S.dossiers[d.id]={id:d.id,...d.data()});softRender14()},()=>{})}catch(e){}
  try{db.collection('contrats').onSnapshot(q=>{S.contrats=q.docs.map(d=>({id:d.id,...d.data()}));softRender14()},()=>{})}catch(e){}};
const ORG={nom:'Association Mon enfant, Ma bataille',forme:'Association loi 1901',siret:'103 769 725 00013',sap:'SAP103769725',rna:'W922023188',adresse:'23 Rue Louis Pouey, 92800 Puteaux',tel:'07 60 08 06 06',email:'monenfantmabataille92@gmail.com',presidente:'Alice MAALOUF',recepisse:'n°2026-234 en date du 06 mai 2026'};
const v=(x,empty)=>x?`<span class="fill">${esc(x)}</span>`:`<span class="empty">${empty||'à compléter'}</span>`;
const fmtD=d=>d?fmt(d):'';
const dIso=ms=>new Date(ms||Date.now()).toISOString().slice(0,10);
/* fin du contrat : 6 mois d'activité, juillet et août non comptés */
function finContrat(debut){if(!debut)return '';const cur=new Date(debut+'T12:00:00');let n=0;while(n<6){const m=cur.getMonth();if(m!==6&&m!==7)n++;cur.setMonth(cur.getMonth()+1)}cur.setDate(cur.getDate()-1);return cur.toISOString().slice(0,10)}
function nextNumeroContrat(){const y=today().slice(0,4);const n=S.contrats.map(c=>(/^MEMB-(\d+)-(\d{4})$/.exec(c.numero||'')||[])).filter(m=>m[2]===y).map(m=>Number(m[1]));return `MEMB-${String((n.length?Math.max(...n):0)+1).padStart(3,'0')}-${y}`}

/* ======================= le contrat (texte du Contrat_MEMB v5) ======================= */
function contratHtml(k){const c=k.contenu||{};const cl=c.client||{};const e=c.enfant||{};const ib=(k.client||{}).iban||'';const sa=k.signatureAsso||{};const sc=k.signatureClient;
  const row=(a,b)=>`<tr><td>${a}</td><td>${b}</td></tr>`;const tarif=c.tarif?Number(c.tarif):55;const eu=x=>String(x.toFixed(2)).replace('.',',');
  return `<div class="ct" id="contrat">
  <div class="head">MON ENFANT, MA BATAILLE</div><div class="meta">Association loi 1901 – Accompagnement éducatif à domicile<br>${ORG.adresse} | N° RNA ${ORG.rna} | N° SIREN 103769725</div>
  <h2>CONTRAT DE PRESTATION ÉDUCATIVE À DOMICILE</h2><div class="sub">Soutien scolaire – Accompagnement éducatif – Développement cognitif<br>Services à la Personne – Mode Prestataire – Déclaration simple</div>
  <div class="sub" style="margin-top:6px">Référence : ${v(k.numero)}</div>
  <h3>ARTICLE PRÉAMBULE – PRÉSENTATION DE L'ASSOCIATION</h3>
  <div class="box"><b>À propos de Mon enfant, Ma bataille</b><br>Mon enfant, Ma bataille est une association loi 1901 fondée par des parents engagés, convaincus qu'un accompagnement éducatif personnalisé, bienveillant et ambitieux peut transformer le parcours de CHAQUE ENFANT — qu'il soit en difficulté scolaire, porteur de troubles neurodéveloppementaux (TSA, TDAH, DYS, TDC, retard de développement…) ou simplement en quête de stimulation et d'épanouissement.<br>Siège social : ${ORG.adresse}<br>N° SAP : ${ORG.sap} | RNA : ${ORG.rna} | Mode d'intervention : PRESTATAIRE<br>Déclaration enregistrée par la DRIEETS Hauts-de-Seine – Récépissé ${ORG.recepisse}</div>
  <div class="box"><b>Nos Prestations</b><br>– Soutien scolaire adapté<br>– Accompagnement éducatif au langage et à la communication<br>– Motricité fine à visée éducative<br>– Activités d'éveil éducatif et sensoriel<br>– Liaison pédagogique avec l'équipe pluridisciplinaire</div>
  <h3>ARTICLE 1 – IDENTIFICATION DES PARTIES</h3>
  <h4>1.1 Le Prestataire</h4><table>${row('Dénomination',ORG.nom)}${row('Forme juridique',ORG.forme)}${row('SIRET',ORG.siret)}${row('N° SAP',ORG.sap)}${row('RNA',ORG.rna)}${row('Adresse',ORG.adresse)}${row('Téléphone',ORG.tel)}${row('Email',ORG.email)}${row('Présidente',ORG.presidente)}</table>
  <h4>1.2 Le Client (représentant légal de l'enfant)</h4><table>${row('Nom et prénom',v([cl.prenom,cl.nom].filter(Boolean).join(' ')))}${row('Adresse',v(cl.adresse))}${row('Téléphone',v(cl.telephone))}${row('Email',v(cl.email))}${row('Date et lieu de naissance',v(cl.naissanceDate?fmtD(cl.naissanceDate)+(cl.naissanceLieu?' à '+cl.naissanceLieu:''):''))}${row('IBAN (pour l’avance immédiate URSSAF)',v(ib))}${row('Lien avec l\'enfant',v(cl.lien))}${row('Autorité parentale',v(cl.autorite))}</table>
  <h4>1.3 L'Enfant bénéficiaire</h4><table>${row('Nom et prénom',v([e.prenom,e.nom].filter(Boolean).join(' ')))}${row('Date de naissance',v(fmtD(e.naissance)))}${row('Classe / niveau scolaire',v(e.classe))}${row('Diagnostic (si applicable)','<span style="color:#666">Non recueilli dans l’application (cadre éducatif). À transmettre, si vous le souhaitez, directement à la coordination.</span>')}</table>
  <h3>ARTICLE 2 – OBJET ET CADRE DE L'INTERVENTION</h3>
  <p>Le présent contrat définit les conditions dans lesquelles l'Association Mon enfant, Ma bataille (ci-après « le Prestataire ») s'engage à fournir des prestations éducatives à domicile au bénéfice de l'enfant désigné à l'article 1.3, dans le cadre du régime des Services à la Personne (SAP) – Déclaration simple.</p>
  <div class="box warn"><b>⚠ CLAUSE DE CADRAGE ÉDUCATIF OBLIGATOIRE</b><br>L'intervenant assure un accompagnement éducatif à domicile. Il n'assure pas la garde de l'enfant, ni l'assistance aux actes de la vie quotidienne (habillage, repas, hygiène). Un parent ou responsable légal reste présent ou joignable à tout moment pendant toute intervention.<br>Le Prestataire n'intervient pas en qualité de service de soins, de rééducation ou de thérapie. Les prestations relèvent exclusivement du soutien scolaire et de l'accompagnement éducatif, conformément aux activités déclarées au titre du récépissé n°2026-234.</div>
  <h4>2.1 Description des prestations</h4><p>Ligne 1 – Accompagnement éducatif enfants en retard de développement : accompagnement éducatif personnalisé à domicile incluant soutien scolaire, activités d'éveil éducatif, accompagnement éducatif au langage et à la communication, activités éducatives de motricité fine et de coordination.</p>
  <h3>ARTICLE 3 – ORGANISATION ET PLANNING DES INTERVENTIONS</h3>
  <h4>3.1 Volume et horaires</h4><table>${row('Volume hebdomadaire',v(c.volume?String(c.volume).replace('.',',')+' heures / semaine':''))}${row('Jours d\'intervention',v(c.jours))}${row('Horaires',v(c.horaires))}${row('Lieu d\'intervention',c.lieuSeances?v(c.lieuSeances):'Domicile du Client – adresse article 1.2')}${row('Durée minimale par séance','1 heure (aucune séance inférieure à 1h ne sera facturée)')}</table>
  <h4>3.2 Intervenant(s)</h4><p>Le Prestataire désignera un ou plusieurs intervenants qualifiés. Le Client sera informé du nom et des qualifications de l'intervenant principal avant la première séance. Le Prestataire agit en qualité d'unique employeur des intervenants. Le Client n'entretient aucune relation contractuelle directe avec eux.</p><p>En cas d'absence imprévue de l'intervenant habituel, le Prestataire s'engage à en informer le Client dans les meilleurs délais et à proposer un remplacement ou un report de séance.</p>
  <h4>3.3 Projet Pédagogique Personnalisé (P3)</h4><p>Un Projet Pédagogique Personnalisé (P3) est co-construit avec la famille dans les 15 jours suivant la signature du présent contrat. Il définit les objectifs éducatifs à 3 et 6 mois, les méthodes retenues, et les indicateurs de progression. Ce document est remis aux deux parties sous forme de document distinct. Il est réévalué à mi-parcours (3 mois) et à l'échéance du contrat.</p>
  <h3>ARTICLE 4 – CONDITIONS FINANCIÈRES</h3>
  <h4>4.1 Tarif</h4><table>${row('Tarif horaire TTC',v(c.tarif?eu(tarif)+' € / heure':''))}${row('Mode de paiement',v(c.paiement||'Virement / CESU préfinancé / Prélèvement'))}${row('Rythme de facturation','Mensuel, en fin de mois')}${row('Délai de règlement','15 jours à compter de la date d\'émission')}</table>
  <h4>4.2 Crédit d'impôt</h4><div class="box">✓ Crédit d'impôt de 50 % sur les dépenses engagées (art. 199 sexdecies CGI).<br>Une attestation fiscale annuelle est adressée avant le 31 mars de chaque année suivante.<br>Exemple : pour ${eu(tarif)} €/h facturés, le coût net famille après crédit d'impôt est de ${eu(tarif/2)} €/h.</div>
  <h4>4.3 Pénalités de retard</h4><p>Tout règlement au-delà de 30 jours calendaires entraîne l'application d'intérêts de retard au taux légal en vigueur. Passé 45 jours sans règlement et après mise en demeure, le Prestataire se réserve le droit de suspendre les interventions.</p>
  <h3>ARTICLE 5 – DURÉE, RENOUVELLEMENT ET RÉSILIATION</h3>
  <h4>5.1 Durée initiale</h4><table>${row('Durée du contrat','6 (six) mois fermes')}${row('Date de début',v(fmtD(c.debut)))}${row('Date d\'échéance initiale',v(fmtD(c.fin)))}</table>
  <h4>5.2 Renouvellement par tacite reconduction</h4><p>À l'issue de la période initiale de 6 mois, le présent contrat se renouvelle automatiquement pour des périodes successives de 6 mois par tacite reconduction, sauf dénonciation par l'une des parties dans les conditions prévues à l'article 5.3.</p><div class="box"><b>Procédure de non-renouvellement :</b> pour ne pas reconduire le contrat à son échéance, chaque partie doit notifier sa décision par courrier (avec accusé de réception) au moins 1 (un) mois avant la date d'échéance. Passé ce délai, le renouvellement est réputé acquis pour 6 mois supplémentaires.</div>
  <h4>5.3 Résiliation en cours de contrat (après la 1ère période)</h4><p>Après la première période de 6 mois, chaque partie peut résilier le contrat avec un préavis d'un (1) mois, notifié par email ou lettre recommandée avec accusé de réception. La résiliation prend effet à l'expiration du préavis. Les séances réalisées pendant le préavis sont dues et facturées.</p><p>Pendant la période initiale de 6 mois, le contrat ne peut être résilié que dans les cas prévus à l'article 6 (résiliation pour motif légitime).</p>
  <h4>5.4 Période d'essai</h4><p>Les 30 premiers jours constituent une période d'observation réciproque. Durant cette période, chaque partie peut mettre fin au contrat avec un préavis de 7 jours, sans justification obligatoire, par simple notification par email.</p>
  <h3>ARTICLE 6 – RÉSILIATION POUR MOTIF LÉGITIME – DROITS DU PRESTATAIRE</h3>
  <p>Le Prestataire se réserve le droit de mettre fin au présent contrat de manière anticipée, avec un préavis de 15 jours (sauf cas d'urgence justifiant une résiliation immédiate), dans les situations suivantes :</p>
  <h4>6.1 Annulations répétées sans motif légitime</h4><p>Constitue un motif légitime de résiliation le fait pour le Client d'annuler ou de reporter des séances de manière répétée sans justification valable. Seuil de déclenchement :<br>– 3 annulations ou reports de dernière minute (moins de 48h avant la séance) sur une période de 2 mois glissants, hors cas de force majeure<br>– ou 5 annulations au total sur la durée d'un contrat de 6 mois</p><p>Les cas de force majeure reconnus incluent : hospitalisation de l'enfant ou d'un parent, urgence médicale documentée, décès dans la famille immédiate, sinistre grave au domicile. Toute autre raison ne constitue pas un cas de force majeure.</p><p>En cas de dépassement du seuil, le Prestataire adressera un avertissement écrit. En l'absence d'amélioration dans les 30 jours suivants, la résiliation pourra être prononcée.</p>
  <h4>6.2 Comportements violents ou dangereux de l'enfant</h4><p>Le Prestataire peut résilier le contrat avec effet immédiat si l'enfant adopte des comportements physiquement violents ou dangereux envers l'intervenant (coups, morsures, projections d'objets, automutilation grave en présence de l'intervenant sans possibilité d'intervention sécurisée…).</p><p>Dans ce cas, le Prestataire notifie la résiliation par écrit avec description factuelle des incidents. Les séances antérieures restent dues. Aucune pénalité n'est appliquée au Client, les comportements violents d'un enfant étant distincts de sa responsabilité personnelle.</p>
  <h4>6.3 Incompatibilité relationnelle</h4><p>En application du principe de confiance réciproque inhérent aux prestations éducatives à domicile, le Prestataire peut mettre fin au contrat en cas d'incompatibilité relationnelle persistante (définie comme une mésentente manifeste et durable entre l'intervenant et l'enfant et/ou sa famille, rendant impossible la poursuite des interventions dans des conditions professionnelles satisfaisantes).</p><p>Ce motif peut être invoqué dès lors que le Coordinateur pédagogique de l'Association l'a constaté et documenté, après au moins deux tentatives de médiation ou d'ajustement.</p>
  <h4>6.4 Absence de progression pédagogique</h4><p>L'équipe pédagogique de l'Association peut décider de mettre fin au contrat si, après 3 mois d'intervention, elle constate objectivement qu'aucun progrès mesurable n'est observé malgré la mise en œuvre rigoureuse du Projet Pédagogique Personnalisé, et si les facteurs d'échec sont extérieurs à l'intervention elle-même (manque d'implication familiale, environnement incompatible, besoins dépassant le cadre éducatif et relevant d'une prise en charge thérapeutique spécialisée exclusive).</p><p>Ce motif sera formalisé dans un compte rendu pédagogique remis au Client, accompagné de recommandations d'orientation vers des professionnels plus adaptés.</p>
  <h4>6.5 Comportement irrespectueux envers les intervenants</h4><p>Tout comportement irrespectueux, injurieux ou harcelant du Client ou d'un membre de sa famille à l'égard des intervenants du Prestataire constitue un motif de résiliation immédiate, sans préavis et sans indemnité.</p>
  <h4>6.6 Non-paiement</h4><p>Le défaut de paiement de deux factures consécutives, après mise en demeure restée sans réponse sous 8 jours ouvrés, autorise le Prestataire à suspendre immédiatement les interventions et à résilier le contrat sans préavis. Les sommes dues restent exigibles.</p>
  <h4>6.7 Situation dépassant le cadre éducatif</h4><p>Si l'état de l'enfant nécessite une prise en charge médicale, thérapeutique ou institutionnelle exclusive que le Prestataire n'est pas habilité à fournir, celui-ci peut mettre fin au contrat avec un préavis de 15 jours, accompagné d'un courrier d'orientation adressé aux parents.</p>
  <h3>ARTICLE 7 – ABSENCES ET ANNULATIONS DU CLIENT</h3>
  <h4>7.1 Délai de prévenance</h4><p>Toute annulation doit être signalée au Prestataire au minimum 48 heures avant la séance planifiée.</p>
  <h4>7.2 Facturation en cas d'annulation tardive</h4><table>${row('Annulation ≥ 48h avant','Séance non facturée – report possible')}${row('Annulation entre 24h et 48h','50 % du tarif horaire facturé')}${row('Annulation < 24h ou absence','100 % du tarif horaire facturé')}${row('Force majeure documentée','Séance non facturée, report prioritaire')}</table>
  <h4>7.3 Vacances et suspension temporaire</h4><p>Des périodes de suspension (vacances scolaires, événement familial) peuvent être convenues d'un commun accord et notifiées au minimum 15 jours à l'avance par email. La suspension ne prolonge pas automatiquement la durée du contrat.</p>
  <h3>ARTICLE 8 – OBLIGATIONS DES PARTIES</h3>
  <h4>8.1 Obligations du Prestataire</h4><p>– Fournir des intervenants formés aux pédagogies adaptées (Montessori, ABA, soutien scolaire différencié)<br>– Respecter et mettre en œuvre le Projet Pédagogique Personnalisé co-construit<br>– Maintenir une communication régulière avec les parents (comptes rendus, bilans)<br>– Respecter la confidentialité absolue sur l'enfant et la famille<br>– Remettre une attestation fiscale annuelle avant le 31 mars<br>– Disposer en permanence d'une assurance RC Professionnelle valide<br>– Ne jamais se substituer aux professionnels de santé (orthophoniste, psychomotricien, médecin)</p>
  <h4>8.2 Obligations du Client</h4><p>– Assurer la présence ou la joignabilité d'un parent ou responsable légal lors de chaque intervention<br>– Fournir un espace calme, sécurisé et adapté à l'intervention éducative<br>– Communiquer tout changement médical, comportemental ou scolaire significatif<br>– Respecter les plannings convenus ou prévenir dans les délais (art. 7)<br>– Régler les factures dans les délais convenus<br>– Ne pas solliciter directement les intervenants de l'Association à titre personnel ou professionnel<br>– Soutenir activement le projet éducatif à domicile (prolongement dans la vie familiale)</p>
  <h3>ARTICLE 9 – CONFIDENTIALITÉ ET PROTECTION DES DONNÉES</h3>
  <p>Toutes les informations relatives à l'enfant (situation scolaire, diagnostic éventuel, comportements, rapports pédagogiques) sont strictement confidentielles. Le Prestataire s'engage à ne les communiquer à aucun tiers sans accord écrit préalable du Client, sauf obligation légale.</p><p>Conformément au Règlement Général sur la Protection des Données (RGPD – Règlement UE 2016/679), le Client dispose d'un droit d'accès, de rectification, de portabilité et de suppression de ses données personnelles. Pour exercer ces droits : ${ORG.email}</p>
  <h4>9.1 Vos avis et témoignages</h4><p>Votre regard sur l’accompagnement de votre enfant compte beaucoup pour nous. Lorsque vous nous confiez un avis positif ou un témoignage, vous nous autorisez, avec toute notre reconnaissance, à le partager pour faire connaître l’association à d’autres familles (site internet, réseaux sociaux, documents de présentation).</p><p>Nous le reprenons fidèlement, uniquement avec votre prénom ou vos initiales, sans jamais citer le nom de votre enfant ni aucune information le concernant. Vous pouvez à tout moment nous demander de ne pas le partager ou de le retirer, par simple message : nous le ferons sans délai, et cela ne change rien à l’accompagnement.</p><p>Partage de mes avis : ${v(c.avis)}</p>
  <h3>ARTICLE 10 – RESPONSABILITÉ ET ASSURANCE</h3>
  <p>Le Prestataire est couvert par une assurance responsabilité civile professionnelle pour les dommages causés dans le cadre de ses interventions. Sa responsabilité ne saurait être engagée en cas de force majeure, d'informations erronées communiquées par le Client, ou de faits extérieurs à son contrôle.</p><p>Les prestations constituent une obligation de moyens et non de résultat. Les progrès de l'enfant dépendent de nombreux facteurs (régularité, implication familiale, stade développemental) et ne peuvent être garantis contractuellement.</p><p>Le Client s'engage à informer le Prestataire de tout risque particulier relatif à la sécurité de l'intervenant au domicile (animal dangereux, matériaux, comportements à risque connus de l'enfant).</p>
  <h3>ARTICLE 11 – DISPOSITIONS DIVERSES</h3>
  <h4>11.1 Non-sollicitation des intervenants</h4><p>Le Client s'engage à ne pas recruter, embaucher ou solliciter directement les intervenants du Prestataire pendant la durée du contrat et dans les 12 mois suivant sa résiliation, sous peine d'une indemnité forfaitaire équivalente à 6 mois de prestations au tarif contractuel.</p>
  <h4>11.2 Dérogation au remboursement lors des vacances scolaires</h4><p>Les séances non réalisées pendant les vacances scolaires officielles, dûment notifiées 15 jours à l'avance, ne sont pas facturées. Le volume annuel contractuel est calculé sur 44 semaines scolaires.</p>
  <h4>11.3 Modification du contrat</h4><p>Toute modification substantielle (tarif, volume horaire, prestations) nécessite un avenant écrit signé des deux parties. Les ajustements de planning ponctuel peuvent être convenus par email.</p>
  <h4>11.4 Loi applicable – Litiges</h4><p>Le présent contrat est soumis au droit français. En cas de différend, les parties s'engagent à rechercher une solution amiable. À défaut d'accord dans les 30 jours, le litige sera soumis au tribunal judiciaire compétent du ressort de Nanterre.</p>
  <h4>11.5 Références réglementaires</h4><p>– Code du travail : art. L7231-1, L7231-2, D7231-1, D7233-1 à D7233-4<br>– Code général des impôts : art. 199 sexdecies (crédit d'impôt SAP)<br>– Récépissé SAP n°2026-234, délivré par la DRIEETS Hauts-de-Seine le 06 mai 2026<br>– RGPD – Règlement UE 2016/679<br>– Arrêté du 22 décembre 2015 relatif aux prix des prestations SAP</p>
  <h3>ARTICLE 12 – SIGNATURES</h3>
  <p>Fait en deux exemplaires originaux, dont un remis à chaque partie (signature électronique, copie par email).</p>
  <p>À ${v(sc&&sc.lieu?sc.lieu:c.lieuSignature)}, le ${sc?v(fmt(dIso(sc.at))):v('','date de la signature')}</p>
  <div class="ksig"><div><b>Pour le Prestataire</b><br>Mon enfant, Ma bataille<br>${esc(sa.nom||ORG.presidente)} – ${esc(sa.qualite||'Présidente')}<br>Signature :${sa.img?`<img src="${sa.img}" alt="Signature de l’association">`:'<br><span class="empty">à apposer</span>'}</div>
   <div><b>Pour le Client</b><br>Nom : ${v(sc?sc.nom:[cl.prenom,cl.nom].filter(Boolean).join(' '))}<br>Qualité : ${v(cl.lien)}<br>Signature :${sc?`<img src="${sc.img}" alt="Signature du client"><div style="font-size:.72rem;color:#555">${esc(sc.mention||'Lu et approuvé')} – signé électroniquement le ${new Date(sc.at).toLocaleString('fr-FR')} · empreinte ${esc(String(sc.empreinte||'').slice(0,16))}</div>`:'<br><span class="empty">en attente</span>'}</div></div>
  </div>`}
const kStatut={brouillon:['Brouillon','gray'],a_signer:['À signer','saf'],signe:['Signé','men'],annule:['Annulé','gray']};
const kPill=k=>{const [l,c]=kStatut[k.statut]||kStatut.brouillon;return `<span class="chip ${c}">${l}</span>`};

/* ======================= signature au doigt ======================= */
function sigPadInit(cv){if(!cv)return;const ctx=cv.getContext('2d');const r=cv.getBoundingClientRect();const dpr=window.devicePixelRatio||1;cv.width=Math.max(1,r.width*dpr);cv.height=Math.max(1,r.height*dpr);ctx.scale(dpr,dpr);ctx.lineWidth=2.4;ctx.lineCap='round';ctx.lineJoin='round';ctx.strokeStyle='#1A2B5C';
  let draw=false,last=null;cv._n=0;const pos=e=>{const b=cv.getBoundingClientRect();return [e.clientX-b.left,e.clientY-b.top]};
  cv.onpointerdown=e=>{draw=true;S.dirty=true;last=pos(e);try{cv.setPointerCapture(e.pointerId)}catch(x){}e.preventDefault()};
  cv.onpointermove=e=>{if(!draw)return;const p=pos(e);ctx.beginPath();ctx.moveTo(last[0],last[1]);ctx.lineTo(p[0],p[1]);ctx.stroke();last=p;cv._n++;e.preventDefault()};
  cv.onpointerup=cv.onpointercancel=()=>{draw=false}}
function sigPadData(cv){if(!cv||(cv._n||0)<12)return null;const w=cv.width,h=cv.height;const out=document.createElement('canvas');const sc=Math.min(1,600/w);out.width=Math.round(w*sc);out.height=Math.round(h*sc);const o=out.getContext('2d');o.fillStyle='#fff';o.fillRect(0,0,out.width,out.height);o.drawImage(cv,0,0,out.width,out.height);return out.toDataURL('image/png')}
ACT['sig-clear']=()=>{const cv=$('#sigK');if(cv)sigPadInit(cv)};

/* ======================= FAMILLE : dossier d'inscription ======================= */
const dossierMe=()=>S.dossiers[meId()]||{statut:'brouillon',parent:{}};
function dossierForm(d){const p={...(d.parent||{})};if(!p.prenom&&p.nom&&p.nom.includes(' ')){const w=p.nom.split(' ');p.prenom=w.shift();p.nom=w.join(' ')}
  const a=d.autreParent||{},e=d.enfant||{},s=d.seances||{},c=d.consentements||{};const lock=['valide','archive'].includes(d.statut);const dis=lock?'disabled':'';
  const f=(id,l,val,type='text',ph='',extra='')=>`<label class="f"><span>${l}</span><input type="${type}" id="${id}" value="${esc(val??'')}" placeholder="${esc(ph)}" ${dis} ${extra}></label>`;
  const sel=(id,l,val,opts)=>`<label class="f"><span>${l}</span><select id="${id}" ${dis}>${opts.map(o=>`<option ${val===o?'selected':''}>${o}</option>`).join('')}</select></label>`;
  return `<div class="stack dz">
  <div class="card stack" style="gap:10px"><div class="card-h" style="margin:0"><div class="l">${it('heart','cor')}<h3>Vous</h3></div></div>
   <div class="fields two">${f('dPp','Prénom',p.prenom)}${f('dPn','Nom',p.nom)}${f('dPd','Date de naissance',p.naissanceDate,'date')}${f('dPl','Lieu de naissance (ville, pays)',p.naissanceLieu)}</div>
   ${f('dPa','Adresse complète',p.adresse,'text','N°, rue, code postal, ville')}
   <div class="fields two">${f('dPt','Téléphone',p.telephone,'tel')}${f('dPe','E-mail',p.email,'email')}${sel('dPk','Lien avec l’enfant',p.lien||'Mère',['Mère','Père','Tuteur légal'])}${sel('dPo','Autorité parentale',p.autorite||'Conjointe',['Conjointe','Exclusive'])}</div></div>
  <div class="card stack" style="gap:10px"><div class="card-h" style="margin:0"><div class="l">${it('euro','men')}<h3>Coordonnées bancaires</h3></div></div>
   <p class="small muted" style="margin:0">Nécessaires pour votre inscription à l’avance immédiate du crédit d’impôt auprès de l’URSSAF. Elles sont chiffrées et ne sont visibles que par vous et la coordination.</p>
   <div class="fields two">${f('dPi','IBAN',p.iban,'text','FR76 …','autocomplete="off" style="text-transform:uppercase"')}${f('dPh','Titulaire du compte',p.titulaire||[p.prenom,p.nom].filter(Boolean).join(' '))}</div>
   ${p.iban_fin&&!lock?'<p class="tiny muted" style="margin:0">Un IBAN est déjà enregistré (affiché masqué). Laissez le champ tel quel pour le garder, ou saisissez-en un nouveau.</p>':''}</div>
  <div class="card stack" style="gap:10px"><div class="card-h" style="margin:0"><div class="l">${it('kids','men')}<h3>Votre enfant</h3></div></div>
   <div class="fields two">${f('dEp','Prénom',e.prenom)}${f('dEn','Nom',e.nom)}${f('dEd','Date de naissance',e.naissance,'date')}${f('dEc','Classe / niveau',e.classe,'text','Ex. CE1')}</div>${f('dEe','École',e.ecole)}</div>
  <div class="card stack" style="gap:10px"><div class="card-h" style="margin:0"><div class="l">${it('cal','cor')}<h3>Les séances souhaitées</h3></div></div>
   ${f('dSa','Adresse des séances (si différente de la vôtre)',s.adresse)}
   <div class="fields three">${f('dSv','Heures par semaine',s.volume,'number','Ex. 2','min="1" step="0.5"')}${f('dSj','Jours souhaités',s.jours,'text','Ex. mardi et jeudi')}${f('dSh','Horaires souhaités',s.horaires,'text','Ex. après 17 h')}</div></div>
  <div class="card stack" style="gap:10px"><div class="card-h" style="margin:0"><div class="l">${it('team','azu')}<h3>L’autre parent (facultatif)</h3></div></div>
   <div class="fields three">${f('dAn','Prénom et nom',a.nom)}${f('dAe','E-mail',a.email,'email')}${f('dAt','Téléphone',a.telephone,'tel')}</div><p class="tiny muted" style="margin:0">Nous pourrons lui ouvrir son propre accès à l’espace famille.</p></div>
  <div class="card stack" style="gap:6px"><div class="card-h" style="margin:0"><div class="l">${it('image','saf')}<h3>Vos accords</h3></div></div>
   <label class="li" style="cursor:pointer"><div class="body small">J’accepte que l’intervenante prenne des photos des réalisations de mon enfant, partagées uniquement dans cet espace</div><input type="checkbox" class="sw" id="dCp" ${c.photos!==false?'checked':''} ${dis}></label>
   <label class="li" style="cursor:pointer"><div class="body small">J’accepte que mes avis positifs soient partagés, avec mon prénom ou mes initiales seulement (article 9.1 du contrat)</div><input type="checkbox" class="sw" id="dCa" ${c.avis!==false?'checked':''} ${dis}></label></div>
  ${lock?'<div class="banner men small">Dossier validé par la coordination. Pour modifier une information, écrivez à la direction (onglet Messages).</div>':`<div class="row"><button class="btn" data-act="dz-send">Envoyer mon dossier</button><button class="btn ghost" data-act="dz-save">Enregistrer le brouillon</button></div><p class="tiny muted">Une fois envoyé, la coordination prépare votre contrat. Vous le recevrez ici pour le lire et le signer avec le doigt.</p>`}</div>`}
function dossierRead(){const g=id=>(($('#'+id)||{}).value||'').trim();const d=dossierMe();const ib=g('dPi');
  const parent={prenom:g('dPp'),nom:g('dPn'),naissanceDate:g('dPd'),naissanceLieu:g('dPl'),adresse:g('dPa'),telephone:g('dPt'),email:g('dPe'),lien:g('dPk'),autorite:g('dPo'),titulaire:g('dPh')};
  if(ib&&!ib.includes('•'))parent.iban=ib;
  return {parent,autreParent:{nom:g('dAn'),email:g('dAe'),telephone:g('dAt')},enfant:{prenom:g('dEp'),nom:g('dEn'),naissance:g('dEd'),classe:g('dEc'),ecole:g('dEe')},seances:{adresse:g('dSa'),volume:g('dSv'),jours:g('dSj'),horaires:g('dSh')},consentements:{photos:!!($('#dCp')||{}).checked,avis:!!($('#dCa')||{}).checked},statut:d.statut==='envoye'?'envoye':'brouillon'}}
async function dzWrite(send){const x=dossierRead();if(send){const miss=[];const P=x.parent;[['prenom','votre prénom'],['nom','votre nom'],['naissanceDate','votre date de naissance'],['naissanceLieu','votre lieu de naissance'],['adresse','votre adresse'],['telephone','votre téléphone']].forEach(([k,l])=>{if(!P[k])miss.push(l)});if(!P.iban&&!(dossierMe().parent||{}).iban_fin)miss.push('votre IBAN');if(!x.enfant.prenom)miss.push('le prénom de votre enfant');if(!x.enfant.naissance)miss.push('sa date de naissance');
    if(miss.length){toast('Il manque : '+miss.join(', ')+'.');return}x.statut='envoye'}
  if(await write('dossiers/'+meId(),x,true)){S.dirty=false;toast(send?'Dossier envoyé : la coordination prépare votre contrat':'Brouillon enregistré');render()}}
Object.assign(ACT,{'dz-save':()=>dzWrite(false),'dz-send':()=>dzWrite(true)});
document.addEventListener('input',e=>{if(e.target.closest&&e.target.closest('.dz,#signBox'))S.dirty=true});
function paInscription(){const d=dossierMe();const sent=d.statut==='envoye';
  return `<div class="stack"><div class="lt"><div class="ttl">${it('heart','cor')}<div><div class="eyebrow">Bienvenue</div><h1>Dossier d’inscription</h1><div class="sub">${sent?'Envoyé le '+(d.envoyeLe?fmt(dIso(d.envoyeLe)):'')+' : la coordination prépare votre contrat.':'Quelques informations pour préparer le contrat de votre enfant.'}</div></div></div></div>
  ${sent?'<div class="banner men small">Merci ! Vous pouvez encore corriger une information et renvoyer le dossier tant que le contrat n’est pas prêt.</div>':''}${dossierForm(d)}
  <div class="row" style="gap:6px"><a class="btn ghost sm" href="/compte">Mon mot de passe</a><a class="btn ghost sm" href="/logout">Se déconnecter</a></div></div>`}
/* ======================= FAMILLE : documents et signature ======================= */
const myContrats=c=>S.contrats.filter(k=>k.statut!=='brouillon'&&k.statut!=='annule'&&(k.parentUid===meId()||(c&&k.cid===c.id))).sort((a,b)=>(b.creeLe||0)-(a.creeLe||0));
function paDocs(c){const ks=myContrats(c);const d=S.dossiers[meId()];
  return `<div class="stack">${paHeader(c,'Documents','Votre contrat et votre dossier')}
  ${ks.filter(k=>k.statut==='a_signer').map(k=>`<div class="banner saf row between" style="gap:10px"><span class="small"><b>Votre contrat ${esc(k.numero||'')} est prêt.</b> Lisez-le et signez-le avec le doigt.</span><button class="btn sm" data-act="nav-contrat" data-k="${k.id}">Lire et signer</button></div>`).join('')}
  <div class="section-t">Contrats</div><div class="card" style="padding:4px 16px">${ks.length?ks.map(k=>`<div class="li clickable" data-act="nav-contrat" data-k="${k.id}">${it('file','lav')}<div class="body"><b class="small">${k.type==='televerse'?esc(k.nom||'Contrat signé'):'Contrat '+esc(k.numero||'')}</b><div class="tiny muted">${k.statut==='signe'?'Signé le '+fmt(dIso(k.signeLe||k.creeLe)):'Reçu le '+fmt(dIso(k.creeLe))}</div></div>${kPill(k)}<span class="chev">${I.chev}</span></div>`).join(''):`<div style="padding:8px 0">${emptyBox('Pas encore de contrat','Il apparaîtra ici dès que la coordination l’aura préparé.','file','lav')}</div>`}</div>
  <div class="section-t">Dossier d’inscription</div><div class="card li clickable" data-act="nav" data-v="p-dossier" style="padding:14px 16px">${it('note','azu')}<div class="body"><b class="small">Mes informations</b><div class="tiny muted">${d?(d.statut==='valide'?'Validé par la coordination':d.statut==='envoye'?'Envoyé, en cours de traitement':'Brouillon'):'À compléter'}</div></div><span class="chev">${I.chev}</span></div></div>`}
function paDossier(c){return `<div class="stack">${paHeader(c,'Mon dossier','')}<button class="btn ghost sm" style="align-self:flex-start" data-act="nav" data-v="p-docs">${I.back}Documents</button>${dossierForm(dossierMe())}</div>`}
function contratView(k,parent){if(k.type==='televerse'){const f=k.fichier||{};return `<div class="card stack" style="gap:10px"><b>${esc(k.nom||'Contrat signé')}</b><div class="tiny muted">Ajouté le ${fmt(dIso(k.creeLe))}</div>${/^image\//.test(f.mime||'')?`<img src="${esc(f.url)}" alt="" style="max-width:100%;border-radius:10px">`:''}<a class="btn" href="${esc(f.url)}" target="_blank" rel="noopener">${I.file}Ouvrir le document</a></div>`}
  const sign=parent&&k.statut==='a_signer';
  return `<div class="row" style="gap:6px">${kPill(k)}<button class="btn ghost sm" data-act="k-print">${I.download}Imprimer ou enregistrer en PDF</button></div>${contratHtml(k)}
  ${sign?`<div class="card stack" style="gap:10px" id="signBox"><h3 style="margin:0">Signer le contrat</h3><p class="small muted" style="margin:0">Signez avec le doigt (ou la souris) dans le cadre blanc.</p><canvas class="sigpad" id="sigK"></canvas><div class="row" style="gap:6px"><button class="btn ghost sm" data-act="sig-clear">Effacer</button></div>
   <label class="f"><span>Fait à (ville)</span><input type="text" id="sigLieu" value="${esc(((k.contenu||{}).lieuSignature)||'')}"></label>
   <label class="row small" style="gap:8px;align-items:flex-start"><input type="checkbox" id="sigOk" style="width:20px;height:20px;flex:none;accent-color:var(--men)">J’ai lu l’ensemble du contrat et je l’accepte (« Lu et approuvé »).</label>
   <button class="btn" data-act="k-sign" data-k="${k.id}">${I.pen}Je signe le contrat</button></div>`:''}`}
function paContrat(c){const k=S.contrats.find(x=>x.id===S.view.kid);if(!k)return paDocs(c);if(k.statut==='a_signer')setTimeout(()=>{const cv=$('#sigK');if(cv&&!cv._init){cv._init=1;sigPadInit(cv)}},60);
  return `<div class="stack">${paHeader(c,'','')}<button class="btn ghost sm" style="align-self:flex-start" data-act="nav" data-v="p-docs">${I.back}Documents</button>${contratView(k,true)}</div>`}
Object.assign(ACT,{
 'nav-contrat':el=>{if(role()==='parent')go('p-contrat',{kid:el.dataset.k});else go('contrat',{kid:el.dataset.k})},
 'k-print':()=>window.print(),
 'k-sign':async el=>{const k=S.contrats.find(x=>x.id===el.dataset.k);if(!k)return;if(!$('#sigOk').checked){toast('Cochez « J’ai lu l’ensemble du contrat ».');return}const img=sigPadData($('#sigK'));if(!img){toast('Signez dans le cadre blanc.');return}
   el.disabled=true;if(await write('contrats/'+k.id,{signatureClient:{img,lieu:($('#sigLieu').value||'').trim()}},true)){toast('Contrat signé, merci ! Il reste dans vos documents.');go('p-docs')}else el.disabled=false},
});

/* ======================= COORDINATION : inscriptions et contrats ======================= */
const dossiersEnvoyes=()=>Object.values(S.dossiers).filter(d=>d.statut==='envoye');
function vDossier(){const d=S.dossiers[S.view.uid];if(!d)return `<div class="card">${emptyBox('Dossier introuvable','')}</div>`;const p=d.parent||{},e=d.enfant||{},s=d.seances||{},a=d.autreParent||{},c=d.consentements||{};
  const kv=(l,x)=>`<div class="kv"><span>${l}</span><div>${x?esc(x):'<span class="muted">—</span>'}</div></div>`;const kids=Object.values(S.children);const linked=d.cid&&S.children[d.cid];
  return `<div class="stack"><button class="btn ghost sm" style="align-self:flex-start" data-act="nav" data-v="atraiter">${I.back}À traiter</button>
  <div class="lt"><div class="ttl">${it('heart','cor')}<div><div class="eyebrow">Dossier d’inscription</div><h1>${esc([e.prenom,e.nom].filter(Boolean).join(' ')||'Enfant')}</h1><div class="sub">${esc([p.prenom,p.nom].filter(Boolean).join(' '))} · ${d.statut==='envoye'?'envoyé le '+fmt(dIso(d.envoyeLe||d.majLe)):d.statut==='valide'?'validé':'brouillon'}</div></div></div></div>
  <div class="grid"><div class="card">${kv('Parent',[p.prenom,p.nom].filter(Boolean).join(' '))}${kv('Né(e) le',p.naissanceDate?fmt(p.naissanceDate)+(p.naissanceLieu?' à '+p.naissanceLieu:''):'')}${kv('Adresse',p.adresse)}${kv('Téléphone',p.telephone)}${kv('E-mail',p.email)}${kv('Lien',p.lien)}${kv('Autorité parentale',p.autorite)}${kv('IBAN',p.iban)}${kv('Titulaire',p.titulaire)}</div>
   <div class="card">${kv('Enfant',[e.prenom,e.nom].filter(Boolean).join(' '))}${kv('Né(e) le',e.naissance?fmt(e.naissance):'')}${kv('Classe',e.classe)}${kv('École',e.ecole)}${kv('Adresse des séances',s.adresse||p.adresse)}${kv('Souhaits',[s.volume?s.volume+' h/semaine':'',s.jours,s.horaires].filter(Boolean).join(' · '))}${kv('Autre parent',[a.nom,a.email,a.telephone].filter(Boolean).join(' · '))}${kv('Photos',c.photos===false?'Non':'Oui')}${kv('Partage des avis',c.avis===false?'Non':'Oui')}</div></div>
  <div class="card stack" style="gap:10px"><div class="card-h" style="margin:0"><div class="l">${it('file','lav')}<h3>Préparer le contrat</h3></div></div>
   ${linked?`<div class="small">Dossier enfant : <b>${esc(childName(linked))}</b></div>`:`<label class="f"><span>Dossier enfant</span><select id="kxC"><option value="">Créer un nouveau dossier à partir de l’inscription</option>${kids.map(k=>`<option value="${k.id}">${esc(childName(k))}</option>`).join('')}</select></label>`}
   <div class="fields three"><label class="f"><span>Intervenante</span><select id="kxI"><option value="">À attribuer</option>${Object.values(S.team).filter(m=>m.role==='intervenante').map(m=>`<option value="${m.id}" ${linked&&linked.intervenante===m.id?'selected':''}>${esc(pName(m.id)||'')}</option>`).join('')}</select></label><label class="f"><span>Tarif (€/h)</span><input type="number" id="kxT" step="0.5" value="${esc(S.settings.tarif||55)}"></label><label class="f"><span>Heures par semaine</span><input type="number" id="kxV" step="0.5" value="${esc(s.volume||2)}"></label></div>
   <div class="fields three"><label class="f"><span>Jours</span><input type="text" id="kxJ" value="${esc(s.jours||'')}"></label><label class="f"><span>Horaires</span><input type="text" id="kxH" value="${esc(s.horaires||'')}"></label><label class="f"><span>Date de début</span><input type="date" id="kxD" value="${addDays(today(),7)}"></label></div>
   <label class="f"><span>Lieu de signature proposé</span><input type="text" id="kxL" value="${esc(((p.adresse||'').match(/\d{5}\s+(.+)$/)||[])[1]||'Puteaux')}"></label>
   ${S.settings.signatureAsso&&S.settings.signatureAsso.img?'<p class="tiny muted" style="margin:0">La signature de l’association est ajoutée automatiquement.</p>':'<p class="tiny" style="margin:0;color:var(--saf-ink)">La signature de l’association n’est pas encore enregistrée (Paramètres › Contrats).</p>'}
   <div class="row"><button class="btn" data-act="kx-go" data-u="${d.id}">${I.file}Préparer et envoyer à la famille</button><button class="btn ghost" data-act="kx-preview" data-u="${d.id}">Aperçu</button></div></div></div>`}
function contratFromDossier(d,o){const p=d.parent||{},e=d.enfant||{},s=d.seances||{},c=d.consentements||{};
  return {numero:nextNumeroContrat(),cid:o.cid,parentUid:d.id,dossierId:d.id,type:'app',statut:'a_signer',creeLe:Date.now(),creePar:meId(),creeParNom:actName(),
   client:{iban:p.iban&&!String(p.iban).includes('•')?p.iban:undefined},
   contenu:{client:{prenom:p.prenom,nom:p.nom,adresse:p.adresse,telephone:p.telephone,email:p.email,naissanceDate:p.naissanceDate,naissanceLieu:p.naissanceLieu,lien:p.lien,autorite:p.autorite},enfant:{prenom:e.prenom,nom:e.nom,naissance:e.naissance,classe:e.classe},
    volume:Number(o.volume)||null,jours:o.jours,horaires:o.horaires,tarif:Number(o.tarif)||null,debut:o.debut,fin:finContrat(o.debut),lieuSeances:s.adresse||'',lieuSignature:o.lieu,avis:c.avis===false?'Je ne souhaite pas':'J’accepte',photos:c.photos!==false,paiement:'Virement / CESU préfinancé / Prélèvement'},
   signatureAsso:{...(S.settings.signatureAsso||{}),nom:(S.settings.signatureAsso||{}).nom||ORG.presidente,qualite:(S.settings.signatureAsso||{}).qualite||'Présidente',at:Date.now()}}}
const kxOpts=()=>({cid:($('#kxC')||{}).value,intervenante:$('#kxI').value,tarif:$('#kxT').value,volume:$('#kxV').value,jours:$('#kxJ').value.trim(),horaires:$('#kxH').value.trim(),debut:$('#kxD').value,lieu:$('#kxL').value.trim()});
Object.assign(ACT,{
 'kx-preview':el=>{const d=S.dossiers[el.dataset.u];const k=contratFromDossier(d,kxOpts());k.client={iban:(d.parent||{}).iban};modal(`<div class="row between"><h2>Aperçu du contrat</h2><button class="btn link" data-act="close">Fermer</button></div>${contratHtml(k)}`)},
 'kx-go':async el=>{const d=S.dossiers[el.dataset.u];const o=kxOpts();if(!o.debut){toast('Indique la date de début.');return}el.disabled=true;let cid=d.cid||o.cid;
   try{if(!cid){const e=d.enfant||{},p=d.parent||{},s=d.seances||{};const adr=s.adresse||p.adresse;if(!adr){toast('Adresse des séances manquante dans le dossier.');el.disabled=false;return}const ref=S.db.collection('children').doc();cid=ref.id;
      const child={prenom:e.prenom||'Enfant',nom:e.nom||'',naissance:e.naissance||'',classe:e.classe||'',etablissement:e.ecole||'',adresse:adr,parentRef:[p.prenom,p.nom].filter(Boolean).join(' '),telephone:p.telephone||'',email:p.email||'',intervenante:o.intervenante||'',createdAt:Date.now(),objectifs:[{},{},{}],inscription:d.id};if(Number(o.tarif))child.tarif=Number(o.tarif);
      if(!await _write15('children/'+cid,child)){el.disabled=false;return}}
     else if(o.intervenante&&S.children[cid]&&!S.children[cid].intervenante)await write('children/'+cid,{intervenante:o.intervenante},true);
     try{const us=(await api15('/api/admin/users')).users;const u=us.find(x=>x.id===d.id);if(u&&!u.children.includes(cid)){const r=await fetch('/api/admin/users/'+encodeURIComponent(d.id),{method:'PATCH',headers:{'Content-Type':'application/json','X-MEMB':'1'},credentials:'same-origin',body:JSON.stringify({children:[...u.children,cid]})});if(!r.ok)throw new Error('lien')}}catch(x){toast('Le compte du parent n’a pas pu être rattaché : fais-le dans le panneau d’administration.')}
     const k=contratFromDossier(d,{...o,cid});if(!k.client.iban)delete k.client.iban;const ref=S.db.collection('contrats').doc();
     if(await write('contrats/'+ref.id,k)){await write('dossiers/'+d.id,{statut:'valide',cid,valideLe:Date.now(),validePar:actName()},true);FAM_AT=0;toast('Contrat '+k.numero+' envoyé à la famille pour signature');go('enfant',{id:cid,tab:'contrats'})}else el.disabled=false}catch(x){toast('Erreur : '+x.message);el.disabled=false}},
 'k-upload':el=>{const cid=el.dataset.c;const i=document.createElement('input');i.type='file';i.accept='application/pdf,image/*';i.onchange=async()=>{const f=i.files[0];if(!f)return;if(f.size>25e6){toast('Fichier trop lourd (25 Mo maximum).');return}toast('Envoi du document…');
   try{const r=await fetch('/api/contrats/upload?cid='+encodeURIComponent(cid),{method:'POST',headers:{'Content-Type':f.type||'application/pdf','X-MEMB':'1'},credentials:'same-origin',body:f});const j=await r.json();if(!r.ok)throw new Error(j.message||'erreur');
     await famLoad(true);const fam=(FAM||[]).find(x=>x.cid===cid);const ref=S.db.collection('contrats').doc();const d={cid,parentUid:fam&&fam.parents[0]?fam.parents[0].id:null,type:'televerse',statut:'signe',nom:f.name.replace(/\.[a-z0-9]+$/i,'')||'Contrat signé',fichier:{id:j.id,url:j.url,mime:j.mime,taille:j.size},creeLe:Date.now(),signeLe:Date.now(),creePar:meId(),creeParNom:actName()};
     if(await write('contrats/'+ref.id,d)){toast('Contrat signé ajouté : la famille peut le consulter');render()}}catch(x){toast('Envoi impossible : '+x.message)}};i.click()},
 'k-cancel':async el=>{if(!confirm('Annuler ce contrat ?'))return;if(await write('contrats/'+el.dataset.k,{statut:'annule',annuleLe:Date.now(),annulePar:actName()},true)){toast('Contrat annulé');render()}},
 'k-new':async el=>{const cid=el.dataset.c;await famLoad(true);const fam=(FAM||[]).find(x=>x.cid===cid);const ps=fam?fam.parents:[];
   modal(`<h2>Nouveau contrat</h2><p class="small muted">Le contrat est préparé à partir du dossier d’inscription du parent choisi. S’il ne l’a pas encore rempli, il le complète dans son espace (Documents › Mon dossier) et vous serez prévenue.</p>${ps.length?`<label class="f"><span>Parent signataire</span><select id="knP">${ps.map(p=>`<option value="${p.id}">${esc(p.name)}${S.dossiers[p.id]&&S.dossiers[p.id].statut!=='brouillon'?'':' (dossier à compléter)'}</option>`).join('')}</select></label>`:'<p class="small" style="color:var(--cor-ink)">Aucun compte parent pour cet enfant : invitez d’abord le parent depuis le panneau d’administration.</p>'}<div class="row" style="margin-top:10px">${ps.length?`<button class="btn" data-act="k-new-go" data-c="${cid}">Continuer</button>`:''}<button class="btn ghost" data-act="close">Fermer</button></div>`)},
 'k-new-go':async el=>{const uid=$('#knP').value;const d=S.dossiers[uid];if(!d||d.statut==='brouillon'){if(!d)await write('dossiers/'+uid,{uid,statut:'brouillon',creeLe:Date.now(),cid:el.dataset.c,parent:{}});else await write('dossiers/'+uid,{cid:el.dataset.c},true);toast('Le parent doit d’abord compléter son dossier dans son espace (Documents).');closeModal();return}
   if(!d.cid)await write('dossiers/'+uid,{cid:el.dataset.c},true);closeModal();go('dossier',{uid})},
});
function tContrats(c){famLoad();const ks=S.contrats.filter(k=>k.cid===c.id).sort((a,b)=>(b.creeLe||0)-(a.creeLe||0));
  return `<div class="card row between" style="gap:10px"><span class="small">Contrats de ${esc(c.prenom)} : préparés dans l’application et signés au doigt, ou contrats papier signés à téléverser.</span><div class="row" style="gap:6px"><button class="btn sm" data-act="k-new" data-c="${c.id}">${I.plus}Préparer un contrat</button><button class="btn ghost sm" data-act="k-upload" data-c="${c.id}">${I.upload}Téléverser un contrat signé</button></div></div>
  <div class="card" style="padding:4px 16px">${ks.length?ks.map(k=>`<div class="li"><div class="body small"><b>${k.type==='televerse'?esc(k.nom||'Contrat signé'):'Contrat '+esc(k.numero||'')}</b><div class="tiny muted">${k.type==='televerse'?'Téléversé':'Préparé'} le ${fmt(dIso(k.creeLe))}${k.signatureClient?' · signé par '+esc(k.signatureClient.nom)+' le '+fmt(dIso(k.signatureClient.at)):''}</div></div>${kPill(k)}<button class="btn ghost sm" data-act="nav-contrat" data-k="${k.id}">Voir</button>${k.statut==='a_signer'?`<button class="btn link sm" data-act="k-cancel" data-k="${k.id}">Annuler</button>`:''}</div>`).join(''):`<div style="padding:8px 0">${emptyBox('Aucun contrat','','file','lav')}</div>`}</div>`}
function vContrat(){const k=S.contrats.find(x=>x.id===S.view.kid);if(!k)return `<div class="card">${emptyBox('Contrat introuvable','')}</div>`;const c=S.children[k.cid];
  return `<div class="stack"><button class="btn ghost sm" style="align-self:flex-start" data-act="back-child-k" data-c="${k.cid||''}">${I.back}${c?esc(c.prenom):'Retour'}</button>${contratView(k,false)}</div>`}
ACT['back-child-k']=el=>el.dataset.c?go('enfant',{id:el.dataset.c,tab:'contrats'}):go('atraiter');
/* signature de l'association (une fois pour toutes) */
ACT['sa-save']=async()=>{const img=sigPadData($('#sigA'));if(!img){toast('Signe dans le cadre blanc.');return}const val={img,nom:($('#saN').value||'').trim()||ORG.presidente,qualite:($('#saQ').value||'').trim()||'Présidente',at:Date.now()};if(await write('settings/main',{signatureAsso:val},true)){S.settings.signatureAsso=val;closeModal();toast('Signature de l’association enregistrée');render()}};
ACT['sa-edit']=()=>{modal(`<h2>Signature de l’association</h2><p class="small muted">Elle sera apposée sur chaque contrat préparé dans l’application.</p><canvas class="sigpad" id="sigA"></canvas><div class="row" style="margin:6px 0"><button class="btn ghost sm" data-act="sa-clear">Effacer</button></div><div class="fields two"><label class="f"><span>Nom</span><input type="text" id="saN" value="${esc((S.settings.signatureAsso||{}).nom||ORG.presidente)}"></label><label class="f"><span>Qualité</span><input type="text" id="saQ" value="${esc((S.settings.signatureAsso||{}).qualite||'Présidente')}"></label></div><div class="row" style="margin-top:10px"><button class="btn" data-act="sa-save">Enregistrer</button><button class="btn ghost" data-act="close">Annuler</button></div>`);setTimeout(()=>sigPadInit($('#sigA')),50)};
ACT['sa-clear']=()=>sigPadInit($('#sigA'));

/* ======================= intégration ======================= */
PA_TABS.splice(PA_TABS.findIndex(x=>x[0]==='p-params'),0,['p-docs','Documents','file','lav']);
const _paBadge16=paBadge;
paBadge=function(k){if(k==='p-docs'){const c=paChild();return myContrats(c).filter(x=>x.statut==='a_signer').length}return _paBadge16(k)};
const _vParent16=vParent;
vParent=function(){const c=paChild();if(S.role==='parent'&&!c)return paInscription();const vn=S.view.name;if(c&&['p-docs','p-dossier','p-contrat'].includes(vn)){return ({'p-docs':paDocs,'p-dossier':paDossier,'p-contrat':paContrat}[vn])(c)}return _vParent16()};
const PA_NEW16=['p-docs','p-dossier','p-contrat'];
const _render16=render;
render=function(){const n=S.view.name;
  if(S.role==='parent'&&!S.viewAs&&S.loaded.children&&!paChild()){renderChrome();$('#navBottom').innerHTML='';$('#navSide').innerHTML='';$('#main').innerHTML=paInscription();return}
  if(PA_NEW16.includes(n)&&role()==='parent'){renderChrome();const m=$('#main');if(!S.loaded.children){m.innerHTML='<div class="loader">Ouverture du carnet…</div>';return}m.innerHTML=vParent();return}
  if(['dossier','contrat'].includes(n)&&isManager()){renderChrome();const m=$('#main');if(!S.loaded.children){m.innerHTML='<div class="loader">Ouverture du carnet…</div>';return}m.innerHTML=n==='dossier'?vDossier():vContrat();return}
  return _render16()};
/* dossier enfant : onglet Contrats (coordination) */
const _vChild16=vChild;
vChild=function(){const tab=S.view.tab||'journal';const extra=tab==='contrats';if(extra)S.view.tab='journal';let h;try{h=_vChild16()}finally{if(extra)S.view.tab=tab}const c=S.children[S.view.id];if(!c||!isManager())return h;
  const n=S.contrats.filter(k=>k.cid===c.id&&k.statut==='a_signer').length;const btn=`<button role="tab" aria-selected="${tab==='contrats'}" data-act="tab" data-t="contrats">${I.file}Contrats${n?' <span class="nb">'+n+'</span>':''}</button>`;
  const ti=h.indexOf('<div class="tabs" role="tablist">');if(ti<0)return h;const te=h.indexOf('</div>',ti);h=h.slice(0,te)+btn+h.slice(te);
  if(extra){h=h.replace(/aria-selected="true" data-act="tab" data-t="journal"/,'aria-selected="false" data-act="tab" data-t="journal"');const te2=h.indexOf('</div>',ti)+6;h=h.slice(0,te2)+'\n  '+tContrats(c)+'</div>'}return h};
/* À traiter : nouvelles inscriptions et contrats en attente de signature */
const _todoItems16=todoItems;
todoItems=function(){const o=_todoItems16();if(!isManager())return o;const d=dossiersEnvoyes();if(d.length)o.inscriptions=d.map(x=>({d:x}));const ks=S.contrats.filter(k=>k.statut==='a_signer'&&Date.now()-(k.creeLe||0)>3*864e5);if(ks.length)o.contrats=ks.map(k=>({k}));return o};
TODO_SEC.unshift(['inscriptions','Nouvelles inscriptions','heart','cor']);TODO_SEC.splice(3,0,['contrats','Contrats non signés depuis 3 jours','file','saf']);
const _todoRow16=todoRow;
todoRow=function(k,x){if(k==='inscriptions'){const e=x.d.enfant||{},p=x.d.parent||{};return `${it('heart','cor')}<div class="body small"><b>${esc([e.prenom,e.nom].filter(Boolean).join(' ')||'Enfant')}</b> · ${esc([p.prenom,p.nom].filter(Boolean).join(' '))}<div class="tiny muted">${esc([e.classe,(x.d.seances||{}).volume?x.d.seances.volume+' h/semaine':''].filter(Boolean).join(' · '))}</div></div><div class="acts"><button class="btn sm" data-act="go-dossier" data-u="${x.d.id}">Préparer le contrat</button></div>`}
  if(k==='contrats'){const c=S.children[x.k.cid]||{prenom:'?'};return `${kidFace(c,32)}<div class="body small"><b>${esc(x.k.numero||'')} · ${esc(c.prenom)}</b><div class="tiny muted">Envoyé il y a ${ago(x.k.creeLe)}, pas encore signé</div></div><div class="acts"><button class="btn ghost sm" data-act="nav-contrat" data-k="${x.k.id}">Voir</button></div>`}return _todoRow16(k,x)};
ACT['go-dossier']=el=>go('dossier',{uid:el.dataset.u});
/* Paramètres : mon adresse (équipe) et signature de l'association */
const _vParams16=vParams;
vParams=function(){let h=_vParams16();const me=meId();const m=S.team[me];
  if(m&&role()!=='parent'){const i=h.indexOf('data-k="bio"');if(i>0){const e=h.indexOf('</label>',i)+8;h=h.slice(0,e)+`<label class="f" style="grid-column:1/-1"><span>Adresse du domicile (départ du GPS et des kilomètres)</span><input type="text" data-member="${me}" data-k="domicile" value="${esc(m.domicile||'')}" placeholder="N°, rue, code postal, ville"></label>`+h.slice(e)}}
  if(isManager()){const sa=S.settings.signatureAsso;const card=`<div class="section-t">Contrats</div><div class="card stack" style="gap:10px"><div class="row between"><div class="small"><b>Signature de l’association</b><div class="tiny muted">Apposée sur chaque contrat préparé dans l’application</div></div><button class="btn ghost sm" data-act="sa-edit">${sa?'Modifier':'Enregistrer la signature'}</button></div>${sa&&sa.img?`<img src="${sa.img}" alt="" style="height:60px;object-fit:contain;align-self:flex-start;background:#fff;border-radius:8px;padding:4px">`:''}
   <div class="small">Lien d’inscription à donner aux nouvelles familles : <b>${esc(location.origin)}/inscription</b> <button class="btn link sm" data-act="copy-insc">Copier</button></div></div>`;const j=h.indexOf('<div class="section-t">Affichage</div>');h=j<0?h+card:h.slice(0,j)+card+h.slice(j)}
  return h};
ACT['copy-insc']=async()=>{try{await navigator.clipboard.writeText(location.origin+'/inscription');toast('Lien copié')}catch(e){toast(location.origin+'/inscription')}};
